(() => {
  const Z=window.Zucco,{state,icon:I,avatar:A,badge:B,btn:BT,STATUS:S,escape:E}=Z;
  const OPTIONS=[{id:S.PRESENT,label:'Present',icon:'check',tone:'success'},{id:S.EXCUSED,label:'Excused',icon:'shield',tone:'warning'},{id:S.ABSENT,label:'Absent',icon:'close',tone:'danger'},{id:S.LATE,label:'Late',icon:'clock',tone:'warning'}];
  Z.attendanceCounts=()=>OPTIONS.map(s=>B(`${s.label} ${state.attendance.filter(a=>a.status===s.id).length}`,s.tone,true)).join('');
  Z.attendanceRows=()=>state.attendance.map(s=>`<tr data-student="${s.id}" data-component="AttendanceRow"><td><div class="row gap-12"><button type="button" class="icon-btn" style="width:auto;height:auto;border-radius:50%" data-action="student-preview:${s.id}" aria-label="Open ${E(s.name)} profile">${A(s.name,s.id==='s1'?'':'slate')}</button><div class="grow"><button class="table-primary" style="border:0;padding:0;background:none;text-align:left" type="button" data-action="student-preview:${s.id}">${E(s.name)}</button><p class="table-secondary mono">#${s.code}</p></div></div></td><td><div class="status-toggle" role="group" aria-label="Attendance for ${E(s.name)}">${OPTIONS.map(option=>`<button type="button" class="status-btn ${option.id} ${s.status===option.id?'selected':''}" aria-pressed="${s.status===option.id}" data-action="status:${s.id}:${option.id}" aria-label="Mark ${E(s.name)} ${option.label.toLowerCase()}">${I(option.icon)}${option.label}</button>`).join('')}</div></td><td><select class="select homework-select" data-homework="${s.id}" aria-label="Homework for ${E(s.name)}">${['Completed','Partial','Not submitted','Excused'].map(v=>`<option ${s.homework===v?'selected':''}>${v}</option>`).join('')}</select></td><td><input type="number" class="input score-input" min="0" max="100" value="${s.grade}" data-grade="${s.id}" aria-label="Grade for ${E(s.name)}" placeholder="—"></td><td><div class="reward-actions"><span class="coin-balance mono" aria-label="${s.coins} coins">${I('coin')}<span>${s.coins}</span></span><button type="button" class="reward-button" data-action="reward:${s.id}:1" aria-label="Give ${E(s.name)} 1 coin">+1${I('coin')}</button><button type="button" class="reward-button" data-action="reward:${s.id}:5" aria-label="Give ${E(s.name)} 5 coins">+5${I('coin')}</button></div></td></tr>`).join('');
  Z.renderers[Z.ROUTES.ATTENDANCE]=()=>Z.heading('Attendance & coin journal','A little recognition. A big difference in every lesson.',BT('View student history','go:'+Z.ROUTES.STUDENT,'users')+BT('Save journal','save-attendance','save','primary'))+
    `<div class="attendance-toolbar"><label><span class="sr-only">Group</span><select class="select" id="attendance-group">${['IELTS Foundation · IF-09','General English · GE-04','Mathematics · MT-12'].map(v=>`<option ${state.attendanceGroup===v?'selected':''}>${v}</option>`).join('')}</select></label><label><span class="sr-only">Lesson date</span><input class="input" type="date" id="attendance-date" value="${state.attendanceDate}" max="2026-11-02"></label><span class="lesson-chip">Lesson 12 · Speaking & fluency</span><div class="grow"></div><span class="row">${A('Madina Karimova','','small')}<span class="caption">Madina Karimova</span></span></div>
    <div class="attendance-summary"><span class="summary-label">${state.attendance.length} students</span><div id="attendance-counts" class="row">${Z.attendanceCounts()}</div><div class="grow"></div>${BT('Mark all present','all-present','checkCircle','small')}</div>
    <section class="panel attendance-scroll"><table class="compact-table attendance-table"><thead><tr><th class="student-col">Student</th><th class="status-col">Attendance status</th><th class="homework-col">Homework</th><th class="score-col">Grade / 100</th><th class="coins-col">Coin rewards</th></tr></thead><tbody id="attendance-rows">${Z.attendanceRows()}</tbody></table><div class="table-footer"><span>Showing all ${state.attendance.length} students in this group</span><span class="row">${I('coin')}Reward effort, progress, and participation</span></div></section>
    <div class="attendance-savebar"><div class="row">${I('shield')}Attendance, grades, and coin rewards are saved together.</div><div class="row gap-16"><span id="save-state" class="save-state ${state.unsaved?'unsaved':''}">${I(state.unsaved?'clock':'checkCircle')}${state.unsaved?'Unsaved changes':state.lastSaved}</span>${BT('Save journal','save-attendance','save','primary')}</div></div>`;
  Z.markStatus=(id,status)=>{const s=state.attendance.find(s=>s.id===id);if(!s||!OPTIONS.some(s=>s.id===status))return;s.status=status;state.unsaved=true;Z.render();};
  Z.reward=(id,amount)=>{const s=state.attendance.find(s=>s.id===id);if(!s)return;s.coins+=amount;state.dirtyRewards+=amount;if(id==='s1')state.coins=s.coins;state.unsaved=true;Z.render();Z.toast(`+${amount} ${amount===1?'coin':'coins'} for ${s.name}`);};
  Z.saveJournal=()=>{const invalid=document.querySelector('.score-input:invalid,#attendance-date:invalid');if(invalid){invalid.reportValidity();invalid.focus();return;}state.unsaved=false;state.lastSaved='All changes saved just now';const count=state.dirtyRewards;state.dirtyRewards=0;Z.render();Z.toast(`Journal saved${count?` · ${count} coins awarded`:''}`);};
})();
